<?php namespace App\Http\Controllers\Api\V1; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Illuminate\Routing\Controller as BaseController; use Illuminate\Http\JsonResponse;
class Controller extends BaseController { use AuthorizesRequests; protected function ok($data=null,$message='Operation successful',$status=200):JsonResponse{return response()->json(['success'=>true,'message'=>$message,'data'=>$data],$status);} protected function fail($message='Request failed',$status=400,$errors=[]):JsonResponse{return response()->json(['success'=>false,'message'=>$message,'errors'=>$errors],$status);} protected function authorizeRole($r,array $roles){if(!in_array($r->user()->role?->slug,$roles,true)) abort(403,'Unauthorized');} }
